<template><button class="pulse-mark" type="button" :class="{ active: modelValue }" :aria-pressed="modelValue" :aria-label="modelValue ? 'Remover dos destaques' : 'Marcar como destaque'" @click="$emit('update:modelValue', !modelValue)"><span aria-hidden="true">✦</span>{{ modelValue ? 'Em destaque' : 'Destacar' }}</button></template>
<script setup>defineProps({ modelValue: Boolean }); defineEmits(['update:modelValue']);</script>
<style scoped>.pulse-mark{display:inline-flex;align-items:center;gap:7px;min-height:40px;padding:8px 12px;border:1px solid #80cfe544;border-radius:999px;color:#9ebdca;background:#102431;cursor:pointer;font-size:11px}.pulse-mark span{font-size:15px}.pulse-mark.active{color:#d8f6ff;border-color:#8fe3f2;background:#174257;box-shadow:0 0 18px #77d7ed22}.pulse-mark.active span{animation:pulse .6s ease}@keyframes pulse{50%{transform:scale(1.45);filter:drop-shadow(0 0 7px #9cecff)}}@media(prefers-reduced-motion:reduce){.pulse-mark.active span{animation:none}}</style>
